-- Starter question bank. Run after 0004_question_bank.sql. Safe to re-run: rows are matched on slug and updated.
-- To add or fix questions later, edit them in the Supabase table editor (public.questions) — no redeploy needed.
-- To retire a question, set active = false instead of deleting it (keeps players' history intact).
--
-- CHALLENGE rows: "answer" is the index of the correct option (options are shuffled per player anyway).
-- Template rows have "template" + "params" instead of options; see lib/game/question-templates.ts.

insert into public.questions (slug, kind, level, topic, emoji, prompt, options, correct_index, explanation, template, params)
select slug, 'CHALLENGE', level::question_level, topic, emoji, prompt, options, answer, why, template, params
from jsonb_to_recordset($json$[

{"slug":"mc-disc-1","level":"BEGINNER","topic":"Discounts","emoji":"🏷️","prompt":"A ₹2,000 jacket is “40% off”. Another shop sells the same jacket for ₹1,300. Which is cheaper?","options":["The 40% off jacket (₹1,200)","The ₹1,300 jacket","They cost the same"],"answer":0,"why":"40% of ₹2,000 is ₹800, so the sale price is ₹1,200 — cheaper than ₹1,300. Always do the maths instead of trusting the loudest sign."},
{"slug":"mc-disc-2","level":"BEGINNER","topic":"Discounts","emoji":"🛒","prompt":"“Buy 2, get 1 free” on ₹300 shampoo. You only need one bottle. What’s the smart move?","options":["Buy 3 — free is free!","Buy just 1 bottle","Buy 2 to be safe"],"answer":1,"why":"A deal only saves money if you needed the extra items. Otherwise you spent ₹600 instead of ₹300."},
{"slug":"mc-disc-3","level":"BEGINNER","topic":"Discounts","emoji":"⏰","prompt":"An app shows “Only 2 left! Offer ends in 5:00”. What is this most likely?","options":["A genuine last chance","A pressure tactic to rush you","A bug in the app"],"answer":1,"why":"Countdown timers and “only X left” create urgency so you skip thinking. Wait and compare."},
{"slug":"mc-scam-1","level":"BEGINNER","topic":"Scams","emoji":"🎰","prompt":"A WhatsApp group promises “guaranteed 5% daily returns” on crypto. What do you do?","options":["Invest a small amount to test","Leave the group and report it","Share it with friends"],"answer":1,"why":"No real investment guarantees high returns. “Guaranteed” plus “daily” is a classic Ponzi sign."},
{"slug":"mc-scam-2","level":"BEGINNER","topic":"Scams","emoji":"💼","prompt":"A “job offer” asks you to pay ₹2,500 as a registration fee before the interview.","options":["Pay it, jobs are hard to find","Refuse — real employers don’t charge fees","Negotiate the fee down"],"answer":1,"why":"Genuine companies never ask candidates to pay for a job or interview."},
{"slug":"mc-upi-1","level":"BEGINNER","topic":"UPI safety","emoji":"📲","prompt":"You’re selling a cycle online. The buyer sends a UPI “collect request” saying you’ll receive ₹4,000 if you enter your PIN.","options":["Enter PIN to receive money","Decline — entering a PIN always sends money","Ask them to send it twice"],"answer":1,"why":"You never need a UPI PIN to receive money. Entering it means you are paying."},
{"slug":"mc-upi-2","level":"BEGINNER","topic":"UPI safety","emoji":"🔢","prompt":"Someone claiming to be from your bank asks for the OTP to “stop a fraudulent transaction”.","options":["Share it quickly to stop the fraud","Never share it and call the bank’s official number","Share half of it"],"answer":1,"why":"Banks never ask for OTPs. Anyone who does is the fraudster."},
{"slug":"mc-upi-3","level":"BEGINNER","topic":"UPI safety","emoji":"🧾","prompt":"A QR code is stuck over the shop’s original one. What’s the risk?","options":["None, QR codes are safe","Money may go to a fraudster’s account","The payment will just fail"],"answer":1,"why":"Check the name shown on your UPI app before paying. Swapped QR stickers are a known trick."},
{"slug":"mc-bud-1","level":"BEGINNER","topic":"Budgeting","emoji":"📊","prompt":"With the 50/30/20 rule and ₹20,000 income, how much should go to savings?","options":["₹2,000","₹4,000","₹10,000"],"answer":1,"why":"20% of ₹20,000 = ₹4,000. Pay yourself first, right on payday."},
{"slug":"mc-bud-2","level":"BEGINNER","topic":"Budgeting","emoji":"☕","prompt":"A ₹150 coffee every working day (22 days) costs you how much a year?","options":["About ₹4,000","About ₹15,000","About ₹40,000"],"answer":2,"why":"₹150 × 22 × 12 ≈ ₹39,600. Small daily spends add up big."},
{"slug":"mc-cred-2","level":"BEGINNER","topic":"Credit","emoji":"📈","prompt":"Which habit helps your credit score most?","options":["Applying for many cards","Paying every bill on time","Never using credit at all"],"answer":1,"why":"On-time payments are the biggest factor in a good credit score."},
{"slug":"mc-inf-1","level":"BEGINNER","topic":"Inflation","emoji":"📉","prompt":"Your savings account pays 3% a year and inflation is 6%. After a year, your money can buy…","options":["More than before","The same as before","Less than before"],"answer":2,"why":"If prices rise faster than your interest, your purchasing power shrinks."},
{"slug":"b-needs","level":"BEGINNER","topic":"Budgeting","emoji":"🏠","prompt":"Which of these is a need, not a want?","options":["Rent for your room","A new phone when yours still works","Concert tickets"],"answer":0,"why":"Needs keep you safe, housed, fed and able to work or study. Everything else is a want — nice, but optional."},
{"slug":"b-wants","level":"BEGINNER","topic":"Budgeting","emoji":"🎬","prompt":"Which of these is a want?","options":["Electricity bill","Groceries","A second streaming subscription"],"answer":2,"why":"Wants are fine in moderation, but they are the first thing to cut when money is tight."},
{"slug":"b-budget-what","level":"BEGINNER","topic":"Budgeting","emoji":"📝","prompt":"A budget is…","options":["A plan for how you’ll spend and save your money","A list of what you bought last year","A type of bank loan"],"answer":0,"why":"A budget is a plan made before you spend, so your money goes where you decide."},
{"slug":"b-track","level":"BEGINNER","topic":"Budgeting","emoji":"🔍","prompt":"What’s the easiest way to find out where your money actually goes?","options":["Guess at the end of the month","Track every spend for one month","Only check big purchases"],"answer":1,"why":"Tracking every spend for a month shows the small leaks that guessing always misses."},
{"slug":"b-pay-first","level":"BEGINNER","topic":"Saving","emoji":"💰","prompt":"When is the best time to put money into savings?","options":["Whatever is left at month end","Right when you get paid","Only when you get a bonus"],"answer":1,"why":"“Pay yourself first”: save on payday, then spend what’s left. Month-end leftovers are usually zero."},
{"slug":"b-ef-what","level":"BEGINNER","topic":"Saving","emoji":"🛟","prompt":"An emergency fund is meant for…","options":["A sudden job loss or medical bill","A big festival sale","A new gadget launch"],"answer":0,"why":"An emergency fund covers real surprises so you don’t have to borrow at high interest."},
{"slug":"b-ef-size","level":"BEGINNER","topic":"Saving","emoji":"📦","prompt":"How big should an emergency fund usually be?","options":["One week of expenses","3–6 months of expenses","5 years of income"],"answer":1,"why":"3–6 months of essential expenses covers most job gaps and emergencies without locking up too much money."},
{"slug":"b-start-young","level":"BEGINNER","topic":"Saving","emoji":"🌱","prompt":"Why start saving young, even in small amounts?","options":["Banks only accept young savers","Money gets more time to grow, and you build the habit","Small amounts don’t matter, so it makes no difference"],"answer":1,"why":"Time is the biggest ingredient in compounding, and saving is a habit that gets easier with practice."},
{"slug":"b-impulse","level":"BEGINNER","topic":"Spending","emoji":"👟","prompt":"You see trendy sneakers you didn’t plan to buy. What’s a good habit?","options":["Buy now before they sell out","Wait 24–48 hours before deciding","Buy two pairs to save on delivery"],"answer":1,"why":"A short wait lets the excitement fade. If you still want them and can afford them, buy them then."},
{"slug":"b-compare","level":"BEGINNER","topic":"Spending","emoji":"🛍️","prompt":"Before buying a ₹15,000 phone online, what’s the smart move?","options":["Buy the first listing you see","Compare prices across shops, including delivery and fees","Buy whichever brand has the most ads"],"answer":1,"why":"The same product often differs by hundreds of rupees between sellers once delivery and fees are added."},
{"slug":"b-mrp","level":"BEGINNER","topic":"Spending","emoji":"🏷️","prompt":"In India, the MRP printed on a product is…","options":["The maximum price a shop can charge","The minimum price a shop can charge","What it cost to make"],"answer":0,"why":"Shops can sell below MRP but not above it. Charging more than MRP is illegal."},
{"slug":"b-bank-why","level":"BEGINNER","topic":"Banking","emoji":"🏦","prompt":"Why keep savings in a bank rather than as cash at home?","options":["It’s safer and can earn interest","Banks double your money every year","Cash at home earns more"],"answer":0,"why":"Bank money is protected from theft and fire, and a savings account pays you a little interest."},
{"slug":"b-interest-save","level":"BEGINNER","topic":"Banking","emoji":"🪙","prompt":"Interest on your savings account is…","options":["Money the bank pays you for keeping your money there","A fee you pay the bank","A government tax"],"answer":0,"why":"When you save, the bank pays you interest. When you borrow, you pay the bank interest."},
{"slug":"b-interest-loan","level":"BEGINNER","topic":"Credit","emoji":"🧮","prompt":"When you borrow money, interest is…","options":["A gift from the lender","The extra you pay back on top of what you borrowed","Only charged if you pay late"],"answer":1,"why":"Borrowing always costs more than the amount you borrow. The interest is the price of using someone else’s money."},
{"slug":"b-debit","level":"BEGINNER","topic":"Banking","emoji":"💳","prompt":"When you pay with a debit card, the money comes from…","options":["Your own bank account","A loan from the bank","The shop"],"answer":0,"why":"A debit card spends your own money. A credit card spends the bank’s money, which you must repay."},
{"slug":"b-credit-card","level":"BEGINNER","topic":"Credit","emoji":"💳","prompt":"Paying with a credit card means…","options":["The shop pays for you","You borrow money that you must repay","It’s free money from the bank"],"answer":1,"why":"Credit cards are short-term loans. Pay the full bill on time and they cost nothing; otherwise interest is very high."},
{"slug":"b-late-bills","level":"BEGINNER","topic":"Credit","emoji":"⏳","prompt":"Paying bills late usually leads to…","options":["Late fees and a lower credit score","Extra discounts","Nothing at all"],"answer":0,"why":"Late payments cost fees right away and stay on your credit record, making future loans harder and costlier."},
{"slug":"b-upi-pin","level":"BEGINNER","topic":"UPI safety","emoji":"🔐","prompt":"Who should know your UPI PIN?","options":["Only you","Your bank’s customer care","Your close friends"],"answer":0,"why":"Your UPI PIN is like the key to your account. No bank, app or friend ever needs it."},
{"slug":"b-upi-receive","level":"BEGINNER","topic":"UPI safety","emoji":"📥","prompt":"To receive money on UPI, you need to…","options":["Enter your UPI PIN","Do nothing — just share your UPI ID or QR code","Pay a small fee first"],"answer":1,"why":"Money comes in without any PIN or fee. Any request for your PIN is a request to take money out."},
{"slug":"b-otp","level":"BEGINNER","topic":"Digital safety","emoji":"🔑","prompt":"An OTP is…","options":["A one-time code that proves it’s you — never share it","A discount code you can share","Your account number"],"answer":0,"why":"An OTP approves a login or payment. Whoever has it can act as you."},
{"slug":"b-password","level":"BEGINNER","topic":"Digital safety","emoji":"🛡️","prompt":"Which is the strongest password?","options":["priya123","Password@1","A long phrase of random words with numbers and symbols"],"answer":2,"why":"Long, unpredictable passphrases are far harder to guess than names, dates or common patterns."},
{"slug":"b-wifi","level":"BEGINNER","topic":"Digital safety","emoji":"📶","prompt":"Is it safe to use banking apps on free public Wi-Fi?","options":["Yes, always","Better to avoid it and use mobile data","Only at night"],"answer":1,"why":"Open networks can be watched or faked. Use mobile data for anything involving money."},
{"slug":"b-atm","level":"BEGINNER","topic":"Digital safety","emoji":"🏧","prompt":"A stranger at the ATM offers to help when your card gets stuck. You should…","options":["Let them help and tell them your PIN","Politely refuse and call your bank’s official number","Leave the card and go home"],"answer":1,"why":"“Helpful strangers” at ATMs often swap cards or watch your PIN. Only trust the bank’s official helpline."},
{"slug":"b-prize","level":"BEGINNER","topic":"Scams","emoji":"🎁","prompt":"A message says you won a phone in a contest you never entered. It’s most likely…","options":["Your lucky day","A scam","A bank offer"],"answer":1,"why":"You can’t win a contest you never entered. These messages exist to get your details or a “delivery fee”."},
{"slug":"b-lend","level":"BEGINNER","topic":"Spending","emoji":"🤝","prompt":"A friend asks to borrow ₹5,000 — the money you’ve saved for your exam fees. Best approach?","options":["Lend it all, they’re your friend","Say no to the fee money; only lend what you can afford to lose","Take a loan so you can lend it"],"answer":1,"why":"Protect money set aside for a goal. If you lend, lend only what you could manage without getting back."},
{"slug":"b-inflation-what","level":"BEGINNER","topic":"Inflation","emoji":"🎈","prompt":"Inflation means…","options":["Prices going up over time","Prices going down over time","Your salary going up"],"answer":0,"why":"With inflation, the same ₹100 buys a little less each year."},
{"slug":"bt-discount-1","level":"BEGINNER","topic":"Discounts","emoji":"👟","prompt":"Shoes priced {price:inr} are {off}% off. What do you pay?","template":"discount_price","params":{"price":{"min":800,"max":4000,"step":100},"off":{"choices":[10,20,25,30,40,50]}},"why":"{off}% of {price:inr} is the discount, so you pay {answer}. Always work out the final price, not just the discount."},
{"slug":"bt-discount-2","level":"BEGINNER","topic":"Discounts","emoji":"🎒","prompt":"A school bag costs {price:inr}. The shop says “{off}% off today”. What’s the final price?","template":"discount_price","params":{"price":{"min":500,"max":2500,"step":50},"off":{"choices":[10,20,30,40]}},"why":"Take {off}% off {price:inr} and you pay {answer}."},
{"slug":"bt-budget-save","level":"BEGINNER","topic":"Budgeting","emoji":"📊","prompt":"Your monthly income is {income:inr}. Under the 50/30/20 rule, how much goes to savings ({share}%)?","template":"budget_share","params":{"income":{"min":10000,"max":60000,"step":2000},"share":{"choices":[20]}},"why":"{share}% of {income:inr} = {answer}. Move it to savings on payday."},
{"slug":"bt-budget-needs","level":"BEGINNER","topic":"Budgeting","emoji":"🏠","prompt":"Your monthly income is {income:inr}. Under the 50/30/20 rule, how much is for needs ({share}%)?","template":"budget_share","params":{"income":{"min":10000,"max":60000,"step":2000},"share":{"choices":[50]}},"why":"{share}% of {income:inr} = {answer} for rent, food, bills and travel."},
{"slug":"bt-habit","level":"BEGINNER","topic":"Budgeting","emoji":"🍟","prompt":"You spend {amount:inr} on snacks {days} days a month. How much is that in a year?","template":"yearly_habit","params":{"amount":{"min":30,"max":200,"step":10},"days":{"choices":[10,15,20,22,25]}},"why":"{amount:inr} × {days} days × 12 months = {answer}. Small daily spends add up."},
{"slug":"bt-emi","level":"BEGINNER","topic":"EMI","emoji":"📱","prompt":"A phone on EMI costs {emi:inr} a month for {months} months, plus a {fee:inr} processing fee. What do you pay in total?","template":"emi_total","params":{"emi":{"min":1000,"max":5000,"step":250},"months":{"choices":[6,9,12]},"fee":{"choices":[199,499,999,1499]}},"why":"{emi:inr} × {months} + {fee:inr} = {answer}. Always add up the full cost of an EMI."},
{"slug":"bt-ef","level":"BEGINNER","topic":"Saving","emoji":"🛟","prompt":"Your monthly expenses are {expenses:inr}. How much do you need for an emergency fund of {months} months?","template":"emergency_fund","params":{"expenses":{"min":8000,"max":40000,"step":1000},"months":{"choices":[3,4,6]}},"why":"{expenses:inr} × {months} months = {answer}."},
{"slug":"bt-goal","level":"BEGINNER","topic":"Saving","emoji":"🚲","prompt":"You want a {target:inr} bicycle in {months} months. How much must you save each month?","template":"goal_saving","params":{"target":{"min":2400,"max":14400,"step":1200},"months":{"choices":[3,4,6,12]}},"why":"{target:inr} ÷ {months} months = {answer} a month. Breaking a goal into monthly steps makes it doable."},
{"slug":"bt-si","level":"BEGINNER","topic":"Interest","emoji":"🏦","prompt":"You keep {P:inr} in a deposit paying {r}% simple interest a year. How much interest do you earn in {n} years?","template":"simple_interest","params":{"P":{"min":5000,"max":50000,"step":5000},"r":{"choices":[4,5,6,7]},"n":{"choices":[2,3]}},"why":"Simple interest = {P:inr} × {r}% × {n} years = {answer}."},

{"slug":"mc-emi-1","level":"INTERMEDIATE","topic":"EMI","emoji":"📱","prompt":"A ₹60,000 phone on “No-cost EMI” of ₹5,000 × 12 months, but there’s a ₹1,999 processing fee. Is it really no-cost?","options":["Yes, it’s exactly ₹60,000","No, you pay ₹61,999 total","You pay less than ₹60,000"],"answer":1,"why":"Fees and lost discounts hide inside “no-cost” EMIs. Add up the total you’ll actually pay."},
{"slug":"mc-emi-2","level":"INTERMEDIATE","topic":"EMI","emoji":"🧾","prompt":"Your take-home pay is ₹30,000. Experts suggest total EMIs stay below roughly…","options":["₹25,000","₹12,000 (about 40%)","Any amount, as long as you pay on time"],"answer":1,"why":"Keep EMIs under ~30–40% of income so emergencies don’t push you into missed payments."},
{"slug":"mc-inf-2","level":"INTERMEDIATE","topic":"Inflation","emoji":"🍛","prompt":"A thali cost ₹100 ten years ago. With ~6% inflation a year, what does it cost now, roughly?","options":["₹106","₹160","₹180"],"answer":2,"why":"6% compounding for 10 years ≈ 1.79×, so about ₹180. Inflation compounds too!"},
{"slug":"mc-ci-1","level":"INTERMEDIATE","topic":"Compound interest","emoji":"🌱","prompt":"Asha invests ₹1,000/month from age 20; Ravi invests ₹2,000/month from age 30. At 12% a year, who has more at 60?","options":["Ravi, he invests double","Asha, thanks to 10 extra years of compounding","Exactly the same"],"answer":1,"why":"Starting early beats investing more later. Time is compounding’s superpower."},
{"slug":"mc-ci-2","level":"INTERMEDIATE","topic":"Compound interest","emoji":"✌️","prompt":"Rule of 72: at 8% a year, money doubles in about…","options":["4 years","9 years","20 years"],"answer":1,"why":"72 ÷ 8 = 9 years. A quick way to estimate doubling time."},
{"slug":"mc-cred-1","level":"INTERMEDIATE","topic":"Credit","emoji":"💳","prompt":"You pay only the “minimum due” on your credit card each month. What happens?","options":["Nothing, you’re fine","The rest grows at ~36–42% a year interest","The bank forgives the rest"],"answer":1,"why":"Credit card interest is among the most expensive debt. Pay the full bill every month."},
{"slug":"i-cibil-range","level":"INTERMEDIATE","topic":"Credit","emoji":"📈","prompt":"In India, CIBIL credit scores range from…","options":["0 to 100","300 to 900","1 to 10"],"answer":1,"why":"Scores run from 300 to 900. Above about 750 is generally considered good."},
{"slug":"i-good-score","level":"INTERMEDIATE","topic":"Credit","emoji":"✅","prompt":"A credit score above about 750 usually means…","options":["Easier loan approval at better interest rates","You can’t borrow any more","You pay higher interest"],"answer":0,"why":"Lenders see a high score as low risk, so they approve faster and often charge less."},
{"slug":"i-check-score","level":"INTERMEDIATE","topic":"Credit","emoji":"🔎","prompt":"Checking your own credit score…","options":["Lowers it a lot","Does not lower it","Is only allowed once in your life"],"answer":1,"why":"Checking your own score is a “soft” enquiry with no effect. Check it at least once a year for errors."},
{"slug":"i-many-apps","level":"INTERMEDIATE","topic":"Credit","emoji":"📨","prompt":"Applying for several loans and credit cards within a few weeks…","options":["Can lower your credit score","Raises your credit score","Has no effect"],"answer":0,"why":"Each application triggers a “hard” enquiry. Many in a short time make you look credit-hungry."},
{"slug":"i-utilisation","level":"INTERMEDIATE","topic":"Credit","emoji":"⚖️","prompt":"You use ₹45,000 of your ₹50,000 credit card limit every month. This…","options":["Is good for your score","Signals credit stress and can hurt your score","Is required to keep the card"],"answer":1,"why":"Using most of your limit suggests you depend on credit. Keep usage under about 30% of the limit."},
{"slug":"i-bnpl","level":"INTERMEDIATE","topic":"Credit","emoji":"🛒","prompt":"“Buy Now, Pay Later” at checkout is…","options":["A discount","A form of credit — missed payments can hurt your score","Free money from the shop"],"answer":1,"why":"BNPL is a loan. It shows up on your credit report and late payments carry fees."},
{"slug":"i-loan-app","level":"INTERMEDIATE","topic":"Credit","emoji":"📵","prompt":"An instant-loan app asks for access to all your contacts and photos. What’s the risk?","options":["None, it’s standard","It may be an unregulated lender that harasses borrowers","It is safer than a bank"],"answer":1,"why":"Borrow only from banks and RBI-regulated lenders. Apps that grab your contacts often use them to shame and threaten."},
{"slug":"i-good-debt","level":"INTERMEDIATE","topic":"Credit","emoji":"🎓","prompt":"Which loan is most likely to improve your future finances?","options":["A personal loan for a holiday","An education loan for a course that raises your earnings","A credit card balance for the latest gadget"],"answer":1,"why":"Debt that raises your future income can pay for itself. Debt for consumption only costs you."},
{"slug":"i-tenure","level":"INTERMEDIATE","topic":"EMI","emoji":"📆","prompt":"Same loan amount and interest rate, but a longer tenure. What happens?","options":["Lower EMI, but more total interest","Lower EMI and less total interest","Higher EMI and less total interest"],"answer":0,"why":"Stretching a loan lowers each payment but you pay interest for more months, so the total cost rises."},
{"slug":"i-fd","level":"INTERMEDIATE","topic":"Banking","emoji":"🔒","prompt":"A fixed deposit (FD) gives you…","options":["A fixed interest rate for a fixed period","Returns linked to the stock market","No interest at all"],"answer":0,"why":"FDs lock your money for a set time at a set rate. Predictable, but usually lower returns than equity over the long run."},
{"slug":"i-fd-break","level":"INTERMEDIATE","topic":"Banking","emoji":"🔨","prompt":"Breaking an FD before it matures usually means…","options":["Bonus interest","A lower rate or a penalty","Nothing changes"],"answer":1,"why":"Banks typically cut the rate for early withdrawal. Keep emergency money somewhere easier to reach."},
{"slug":"i-dicgc","level":"INTERMEDIATE","topic":"Banking","emoji":"🛡️","prompt":"Bank deposits in India are insured by DICGC up to…","options":["₹1 lakh in total","₹5 lakh per depositor per bank","Any amount"],"answer":1,"why":"Deposit insurance covers up to ₹5 lakh per depositor per bank, including interest. Large sums can be spread across banks."},
{"slug":"i-rd","level":"INTERMEDIATE","topic":"Banking","emoji":"🔁","prompt":"A recurring deposit (RD) lets you…","options":["Deposit a fixed amount every month and earn interest","Withdraw any time with no interest","Buy company shares"],"answer":0,"why":"An RD builds a saving habit with fixed monthly deposits at a fixed rate."},
{"slug":"i-nominee","level":"INTERMEDIATE","topic":"Banking","emoji":"👪","prompt":"Why add a nominee to your bank account and investments?","options":["To get a higher interest rate","So your family can claim the money easily if something happens to you","It’s needed to use UPI"],"answer":1,"why":"Without a nominee, families can face months of paperwork to reach the money."},
{"slug":"i-rbi","level":"INTERMEDIATE","topic":"Regulators","emoji":"🏛️","prompt":"Who regulates banks in India?","options":["SEBI","RBI","IRDAI"],"answer":1,"why":"The Reserve Bank of India regulates banks. SEBI oversees markets and IRDAI oversees insurance."},
{"slug":"i-sebi","level":"INTERMEDIATE","topic":"Regulators","emoji":"🏛️","prompt":"Who regulates the stock market and mutual funds in India?","options":["RBI","SEBI","IRDAI"],"answer":1,"why":"SEBI regulates stock exchanges, brokers, mutual funds and investment advisers."},
{"slug":"i-irdai","level":"INTERMEDIATE","topic":"Regulators","emoji":"🏛️","prompt":"Insurance companies in India are regulated by…","options":["IRDAI","SEBI","RBI"],"answer":0,"why":"IRDAI regulates insurers and handles policyholder protection rules."},
{"slug":"i-mf","level":"INTERMEDIATE","topic":"Investing","emoji":"🧺","prompt":"A mutual fund…","options":["Pools money from many investors to buy a mix of assets","Is a type of bank account","Guarantees fixed returns"],"answer":0,"why":"A fund manager invests the pooled money. Returns go up and down with what the fund holds."},
{"slug":"i-sip","level":"INTERMEDIATE","topic":"Investing","emoji":"📅","prompt":"A SIP (Systematic Investment Plan) means…","options":["Investing a fixed amount regularly, like every month","Investing one big lump sum","Taking a loan to invest"],"answer":0,"why":"SIPs automate investing and spread your purchases across good and bad market days."},
{"slug":"i-rca","level":"INTERMEDIATE","topic":"Investing","emoji":"⚖️","prompt":"Investing the same amount every month means you buy…","options":["The same number of units every time","More units when prices are low, fewer when high","Only when prices are high"],"answer":1,"why":"This is rupee cost averaging: a fixed amount automatically buys more when prices dip."},
{"slug":"i-sip-fall","level":"INTERMEDIATE","topic":"Investing","emoji":"📉","prompt":"The market falls 10% while you’re running a long-term SIP. A sensible move is…","options":["Keep investing as planned","Stop the SIP and sell everything","Borrow money to invest more"],"answer":0,"why":"Falls are normal. Continuing your SIP buys more units cheaply; panic-selling locks in the loss."},
{"slug":"i-diversify","level":"INTERMEDIATE","topic":"Investing","emoji":"🧩","prompt":"Why spread money across different investments?","options":["It guarantees a profit","One bad investment hurts you less","It increases your taxes"],"answer":1,"why":"Diversification doesn’t remove risk, but it stops one failure from sinking your whole plan."},
{"slug":"i-share","level":"INTERMEDIATE","topic":"Investing","emoji":"🏢","prompt":"Owning a share of a company means…","options":["You own a small part of that company","You lent the company money","You work for the company"],"answer":0,"why":"Shareholders own a slice of the business and share in its growth (and its losses)."},
{"slug":"i-bond","level":"INTERMEDIATE","topic":"Investing","emoji":"📜","prompt":"When you buy a bond, you are…","options":["Buying part-ownership of a company","Lending money in return for interest","Placing a bet"],"answer":1,"why":"A bond is a loan to a government or company, which pays interest and returns your money at maturity."},
{"slug":"i-risk","level":"INTERMEDIATE","topic":"Investing","emoji":"🎢","prompt":"In general, investments with higher potential returns…","options":["Carry higher risk","Carry no risk","Are guaranteed by the government"],"answer":0,"why":"Higher expected returns are the reward for accepting bigger ups and downs."},
{"slug":"i-nifty","level":"INTERMEDIATE","topic":"Investing","emoji":"📊","prompt":"The Nifty 50 index tracks…","options":["50 large companies listed on the NSE","50 banks","50 mutual funds"],"answer":0,"why":"The Nifty 50 is a basket of 50 large Indian companies, used as a benchmark for the market."},
{"slug":"i-index-fund","level":"INTERMEDIATE","topic":"Investing","emoji":"🧭","prompt":"An index fund…","options":["Picks hot stocks every day","Copies a market index, usually at low cost","Guarantees the index return plus 5%"],"answer":1,"why":"Index funds simply hold what the index holds, which keeps costs low."},
{"slug":"i-term","level":"INTERMEDIATE","topic":"Insurance","emoji":"☂️","prompt":"Term life insurance mainly…","options":["Pays your family a large sum if you die during the term","Is an investment with high returns","Covers phone damage"],"answer":0,"why":"Term insurance is pure protection: low premium, large cover, no maturity payout."},
{"slug":"i-health","level":"INTERMEDIATE","topic":"Insurance","emoji":"🏥","prompt":"Why buy health insurance while young and healthy?","options":["It’s free for young people","Premiums are lower and you’re covered before problems start","Young people never get sick"],"answer":1,"why":"Buying early locks in lower premiums and avoids exclusions for conditions found later."},
{"slug":"i-mixed","level":"INTERMEDIATE","topic":"Insurance","emoji":"🧃","prompt":"Policies that mix insurance and investment often give…","options":["The best of both","Less cover and lower returns than buying the two separately","Guaranteed high returns"],"answer":1,"why":"Bundled policies tend to have high charges. Many people do better with term insurance plus separate investments."},
{"slug":"it-si","level":"INTERMEDIATE","topic":"Interest","emoji":"🏦","prompt":"You lend {P:inr} at {r}% simple interest a year. How much interest is due after {n} years?","template":"simple_interest","params":{"P":{"min":10000,"max":100000,"step":5000},"r":{"choices":[5,6,7,8,9]},"n":{"choices":[2,3,4,5]}},"why":"{P:inr} × {r}% × {n} years = {answer}. Simple interest is only paid on the original amount."},
{"slug":"it-ci","level":"INTERMEDIATE","topic":"Compound interest","emoji":"🌱","prompt":"{P:inr} grows at {r}% a year, compounded yearly. Roughly what is it worth after {n} years?","template":"compound_amount","params":{"P":{"min":10000,"max":100000,"step":10000},"r":{"choices":[6,8,10,12]},"n":{"choices":[3,5]}},"why":"{P:inr} × (1 + {r}%)^{n} ≈ {answer}. Each year’s growth earns growth too."},
{"slug":"it-infl","level":"INTERMEDIATE","topic":"Inflation","emoji":"🎟️","prompt":"A movie ticket costs {price:inr} today. If prices rise {r}% a year, roughly what will it cost in {n} years?","template":"inflation_price","params":{"price":{"min":150,"max":500,"step":10},"r":{"choices":[5,6,7]},"n":{"choices":[5,10]}},"why":"{price:inr} × (1 + {r}%)^{n} ≈ {answer}. Inflation compounds just like interest."},
{"slug":"it-72","level":"INTERMEDIATE","topic":"Compound interest","emoji":"✌️","prompt":"Using the Rule of 72, at {r}% a year your money doubles in about…","template":"rule_of_72","params":{"r":{"choices":[4,6,8,9,12]}},"why":"72 ÷ {r} = {answer}."},
{"slug":"it-stack","level":"INTERMEDIATE","topic":"Discounts","emoji":"🧥","prompt":"A {price:inr} jacket is {a}% off, and your coupon takes another {b}% off the sale price. What’s the final price?","template":"stacked_discount","params":{"price":{"min":1000,"max":5000,"step":100},"a":{"choices":[20,30,40,50]},"b":{"choices":[10,20]}},"why":"The coupon applies to the reduced price, so you pay {answer} — not {a}% + {b}% off the original."},
{"slug":"it-real","level":"INTERMEDIATE","topic":"Inflation","emoji":"📉","prompt":"Your FD pays {rate}% a year and inflation is {inflation}%. Your real return is roughly…","template":"real_return","params":{"rate":{"choices":[6,6.5,7,7.5]},"inflation":{"choices":[3,4,5]}},"why":"Real return ≈ {rate}% − {inflation}% = {answer}. That’s how much your buying power actually grows."},
{"slug":"it-sip","level":"INTERMEDIATE","topic":"Investing","emoji":"📅","prompt":"You invest {amount:inr} a month through a SIP for {years} years. How much money did you put in, before any returns?","template":"sip_invested","params":{"amount":{"min":500,"max":5000,"step":500},"years":{"choices":[3,5,10]}},"why":"{amount:inr} × 12 × {years} = {answer}. Anything above that at the end is growth."},
{"slug":"it-util","level":"INTERMEDIATE","topic":"Credit","emoji":"⚖️","prompt":"Your credit card limit is {limit:inr} and you’ve used {used:inr}. What is your credit utilisation?","template":"utilisation","params":{"limit":{"choices":[50000,100000]},"used":{"min":5000,"max":45000,"step":5000}},"why":"{used:inr} ÷ {limit:inr} = {answer}. Lenders like to see it under about 30%."},
{"slug":"it-pp","level":"INTERMEDIATE","topic":"Inflation","emoji":"💸","prompt":"You keep {amount:inr} in cash for {n} years while inflation runs at {r}% a year. Roughly what is it worth in today’s money?","template":"purchasing_power","params":{"amount":{"min":10000,"max":100000,"step":10000},"r":{"choices":[5,6,7]},"n":{"choices":[5,10]}},"why":"{amount:inr} ÷ (1 + {r}%)^{n} ≈ {answer}. Cash that doesn’t grow quietly loses value."},

{"slug":"a-expense-ratio","level":"ADVANCED","topic":"Investing","emoji":"🧾","prompt":"Two similar index funds charge 0.2% and 1.5% a year (expense ratio). Over 20 years…","options":["The low-cost fund likely leaves you noticeably more money","There’s no real difference","The expensive one is always better"],"answer":0,"why":"Costs compound against you every year. A 1.3% yearly gap can eat a large share of long-term gains."},
{"slug":"a-direct","level":"ADVANCED","topic":"Investing","emoji":"🎯","prompt":"Compared with “regular” plans, “direct” mutual fund plans…","options":["Have lower expense ratios because no distributor commission is paid","Are riskier","Have guaranteed returns"],"answer":0,"why":"Same fund, same portfolio — direct plans just skip the commission, so more return stays with you."},
{"slug":"a-nav","level":"ADVANCED","topic":"Investing","emoji":"🏷️","prompt":"Fund A has an NAV of ₹10 and Fund B has an NAV of ₹100. Which is cheaper to invest in?","options":["Fund A","Fund B","Neither — NAV alone doesn’t make a fund cheap or expensive"],"answer":2,"why":"NAV is just the price per unit. What matters is what the fund holds, its costs and its returns."},
{"slug":"a-bond-rates","level":"ADVANCED","topic":"Investing","emoji":"📜","prompt":"When interest rates rise, the prices of existing bonds usually…","options":["Fall","Rise","Stay exactly the same"],"answer":0,"why":"New bonds pay more, so older lower-rate bonds become less attractive and their prices drop."},
{"slug":"a-pe","level":"ADVANCED","topic":"Investing","emoji":"🔬","prompt":"A share’s P/E ratio compares…","options":["Its price with the company’s earnings per share","Profit with number of employees","Price with dividends paid"],"answer":0,"why":"P/E shows how many rupees investors pay for each rupee of yearly profit. High P/E means high expectations."},
{"slug":"a-dividend","level":"ADVANCED","topic":"Investing","emoji":"🍰","prompt":"A dividend is…","options":["A share of company profits paid to shareholders","A fee for holding shares","A government tax on shares"],"answer":0,"why":"Companies may pay out part of their profit as dividends. It’s not guaranteed and can be cut."},
{"slug":"a-rebalance","level":"ADVANCED","topic":"Investing","emoji":"⚖️","prompt":"Your plan is 60% equity, 40% debt. After a rally it’s 75/25. Rebalancing means…","options":["Moving back towards 60/40","Buying even more equity","Never changing anything"],"answer":0,"why":"Rebalancing sells some of what rose and buys what lagged, keeping your risk where you planned it."},
{"slug":"a-goal-near","level":"ADVANCED","topic":"Investing","emoji":"🏁","prompt":"Money for a goal that’s only 2 years away should usually be…","options":["Moved towards safer options like debt funds or FDs","Moved fully into small-cap stocks","Kept 100% in equity"],"answer":0,"why":"Near a goal there’s no time to recover from a crash, so protect what you’ve built."},
{"slug":"a-timing","level":"ADVANCED","topic":"Investing","emoji":"⏱️","prompt":"Trying to time the market (sell before falls, buy before rises)…","options":["Rarely works consistently, and missing a few of the best days hurts returns","Is easy with practice","Guarantees profit"],"answer":0,"why":"The best and worst days often come close together. Staying invested usually beats jumping in and out."},
{"slug":"a-ppf","level":"ADVANCED","topic":"Tax & savings schemes","emoji":"📘","prompt":"The Public Provident Fund (PPF) has a lock-in period of…","options":["1 year","3 years","15 years"],"answer":2,"why":"PPF runs for 15 years (extendable), with partial withdrawals allowed only after some years."},
{"slug":"a-elss","level":"ADVANCED","topic":"Tax & savings schemes","emoji":"📗","prompt":"ELSS (tax-saving) mutual funds have a lock-in of…","options":["None","3 years","15 years"],"answer":1,"why":"ELSS has the shortest lock-in among the popular Section 80C options: 3 years."},
{"slug":"a-80c","level":"ADVANCED","topic":"Tax & savings schemes","emoji":"🧮","prompt":"Under the old tax regime, Section 80C lets you deduct investments of up to…","options":["₹50,000","₹1.5 lakh","₹10 lakh"],"answer":1,"why":"PPF, ELSS, EPF and similar together count towards the ₹1.5 lakh limit under the old regime."},
{"slug":"a-nps","level":"ADVANCED","topic":"Tax & savings schemes","emoji":"👴","prompt":"The National Pension System (NPS) is mainly meant for…","options":["Retirement savings","Short-term trading","Buying gold"],"answer":0,"why":"NPS is a long-term, low-cost retirement product, with most money locked until 60."},
{"slug":"a-term-cover","level":"ADVANCED","topic":"Insurance","emoji":"☂️","prompt":"A common rule of thumb for how much term insurance cover to buy is about…","options":["1× your annual income","10–15× your annual income","A flat ₹10,000"],"answer":1,"why":"The cover should replace years of income for your family and clear any big loans."},
{"slug":"a-copay","level":"ADVANCED","topic":"Insurance","emoji":"🏥","prompt":"Your health policy has a 20% co-pay. A covered hospital bill is ₹1,00,000. You pay…","options":["₹20,000","₹80,000","Nothing"],"answer":0,"why":"Co-pay is your fixed share of every claim: 20% of ₹1,00,000 = ₹20,000. Lower co-pay usually means a higher premium."},
{"slug":"a-disclose","level":"ADVANCED","topic":"Insurance","emoji":"📋","prompt":"Hiding an existing health condition when buying insurance can…","options":["Lead to your claim being rejected","Lower your premium safely forever","Make no difference"],"answer":0,"why":"Insurers can reject claims for non-disclosure. Declare everything honestly up front."},
{"slug":"a-liquid","level":"ADVANCED","topic":"Investing","emoji":"💧","prompt":"Which of these is the least liquid (hardest to turn into cash quickly)?","options":["A savings account","A liquid mutual fund","A flat you own"],"answer":2,"why":"Property can take months to sell. Liquidity matters for money you might need soon."},
{"slug":"a-ef-where","level":"ADVANCED","topic":"Saving","emoji":"🛟","prompt":"The best place for an emergency fund is…","options":["Shares, for the highest return","A savings account, sweep FD or liquid fund you can reach quickly","Property"],"answer":1,"why":"Emergency money must be safe and reachable within a day or two, not chasing returns."},
{"slug":"a-cc-full","level":"ADVANCED","topic":"Credit","emoji":"💳","prompt":"Using a credit card wisely means…","options":["Paying the full statement amount by the due date","Paying only the minimum due","Withdrawing cash from it when short"],"answer":0,"why":"Paying in full means you never pay interest and still build a good credit history."},
{"slug":"a-cash-advance","level":"ADVANCED","topic":"Credit","emoji":"🏧","prompt":"Withdrawing cash from a credit card at an ATM…","options":["Is free","Usually charges a fee and interest from day one","Earns extra reward points"],"answer":1,"why":"Cash advances skip the interest-free period. It’s one of the most expensive ways to borrow."},
{"slug":"a-repo","level":"ADVANCED","topic":"Economy","emoji":"🏛️","prompt":"When the RBI raises the repo rate, EMIs on floating-rate loans generally…","options":["Go up (or the loan tenure gets longer)","Go down","Stay the same forever"],"answer":0,"why":"Banks pass on higher policy rates to floating-rate borrowers through higher EMIs or longer tenures."},
{"slug":"a-floating","level":"ADVANCED","topic":"Credit","emoji":"🌊","prompt":"The interest rate on a floating-rate home loan…","options":["Never changes","Can change with benchmark rates","Can only fall"],"answer":1,"why":"Floating rates move with a benchmark such as the repo rate, up or down."},
{"slug":"a-prepay","level":"ADVANCED","topic":"Credit","emoji":"✂️","prompt":"Prepaying part of a loan early mainly…","options":["Reduces the total interest you pay","Increases the total interest","Makes no difference"],"answer":0,"why":"Prepayment cuts the outstanding amount, so less interest builds up on it."},
{"slug":"a-compound-freq","level":"ADVANCED","topic":"Compound interest","emoji":"🔄","prompt":"The same 8% yearly rate, compounded monthly vs yearly. Which grows more?","options":["Monthly","Yearly","They’re exactly equal"],"answer":0,"why":"More frequent compounding adds interest on interest sooner, so the effective yearly rate is slightly higher."},
{"slug":"a-gold","level":"ADVANCED","topic":"Investing","emoji":"🥇","prompt":"Gold’s usual role in a portfolio is…","options":["A diversifier that may hold up when stocks fall","A guaranteed high return","A replacement for insurance"],"answer":0,"why":"Gold often behaves differently from equities, which can smooth a portfolio, but it has long flat stretches too."},
{"slug":"a-equity-age","level":"ADVANCED","topic":"Investing","emoji":"🧓","prompt":"Why hold more equity when retirement is far away, and less as it gets close?","options":["Early on there’s time to recover from crashes; near retirement there isn’t","Equity is illegal after 50","Shares stop paying dividends after 60"],"answer":0,"why":"Time lets you ride out falls. Close to needing the money, a crash can permanently hurt your plans."},
{"slug":"a-ponzi","level":"ADVANCED","topic":"Scams","emoji":"🔺","prompt":"A scheme pays early members “returns” using money from new members. This is…","options":["A Ponzi scheme","A mutual fund","A fixed deposit"],"answer":0,"why":"Ponzi schemes collapse when new money slows. Early “profits” are bait to bring in more victims."},
{"slug":"a-pump","level":"ADVANCED","topic":"Scams","emoji":"🚀","prompt":"A Telegram channel suddenly hypes a tiny unknown stock “set to go 10× this week”. Most likely?","options":["A pump-and-dump: promoters sell to the buyers they attract","A genuine insider tip","An official SEBI recommendation"],"answer":0,"why":"Operators buy cheap, hype the stock, then dump it on followers. SEBI acts against such schemes."},
{"slug":"a-ria","level":"ADVANCED","topic":"Investing","emoji":"🔍","prompt":"Before following someone’s paid investment tips, you should check…","options":["Their follower count","Whether they’re SEBI-registered","How expensive their car is"],"answer":1,"why":"Only SEBI-registered advisers and research analysts may give paid investment advice. Their registration can be checked on SEBI’s website."},
{"slug":"a-mule","level":"ADVANCED","topic":"Scams","emoji":"🐴","prompt":"Someone offers you ₹5,000 to “rent” your bank account for their transactions. This is…","options":["Easy side income","Money muling — illegal, and you can be prosecuted","Normal banking"],"answer":1,"why":"Fraudsters move stolen money through rented accounts. The account owner faces frozen accounts and criminal cases."},
{"slug":"a-digital-arrest","level":"ADVANCED","topic":"Scams","emoji":"🚔","prompt":"A video caller in uniform says you’re under “digital arrest” and must transfer money to clear your name. What’s true?","options":["You must comply immediately","No Indian agency arrests people or collects money over a video call — it’s a scam","Pay half now and half later"],"answer":1,"why":"“Digital arrest” doesn’t exist. Hang up, don’t pay, and report it on 1930 or cybercrime.gov.in."},
{"slug":"a-sim-swap","level":"ADVANCED","topic":"Digital safety","emoji":"📵","prompt":"Your phone suddenly loses network for hours and bank SMS stop arriving. A possible risk is…","options":["Just a weak signal, ignore it","SIM-swap fraud — contact your operator and bank quickly","A software update"],"answer":1,"why":"Fraudsters can get a duplicate SIM to receive your OTPs. Act fast if your SIM stops working unexpectedly."},
{"slug":"a-aadhaar-lock","level":"ADVANCED","topic":"Digital safety","emoji":"🔏","prompt":"To protect against Aadhaar-enabled payment fraud, you can…","options":["Lock your Aadhaar biometrics through UIDAI or the mAadhaar app","Share your Aadhaar number widely","Do nothing; it can’t be protected"],"answer":0,"why":"Locked biometrics can’t be used for authentication until you unlock them yourself."},
{"slug":"at-ci","level":"ADVANCED","topic":"Compound interest","emoji":"🌳","prompt":"You invest a lump sum of {P:inr} at {r}% a year, compounded yearly. Roughly what is it worth after {n} years?","template":"compound_amount","params":{"P":{"min":50000,"max":500000,"step":50000},"r":{"choices":[8,10,12]},"n":{"choices":[10,15,20]}},"why":"{P:inr} × (1 + {r}%)^{n} ≈ {answer}. Over long periods, compounding does most of the work."},
{"slug":"at-card","level":"ADVANCED","topic":"Credit","emoji":"💳","prompt":"You carry a {balance:inr} credit card balance at {apr}% a year. Roughly how much interest is added in one month?","template":"card_interest","params":{"balance":{"min":10000,"max":100000,"step":5000},"apr":{"choices":[36,40,42]}},"why":"{apr}% a year is about {apr}/12 % a month: {balance:inr} × that ≈ {answer} every month, before any late fees."},
{"slug":"at-infl","level":"ADVANCED","topic":"Inflation","emoji":"🏠","prompt":"Your household spends {price:inr} a month today. At {r}% inflation, roughly what will the same lifestyle cost per month in {n} years?","template":"inflation_price","params":{"price":{"min":20000,"max":80000,"step":5000},"r":{"choices":[5,6,7]},"n":{"choices":[15,20,25]}},"why":"{price:inr} × (1 + {r}%)^{n} ≈ {answer}. Retirement plans must account for this."},
{"slug":"at-pp","level":"ADVANCED","topic":"Inflation","emoji":"🧓","prompt":"You plan to retire on {amount:inr} a month, {n} years from now. At {r}% inflation, roughly what is that worth in today’s money?","template":"purchasing_power","params":{"amount":{"min":50000,"max":200000,"step":25000},"r":{"choices":[5,6]},"n":{"choices":[20,25,30]}},"why":"{amount:inr} ÷ (1 + {r}%)^{n} ≈ {answer} in today’s money. Big future numbers shrink a lot."},
{"slug":"at-real","level":"ADVANCED","topic":"Inflation","emoji":"📉","prompt":"A savings product pays {rate}% a year and inflation is {inflation}%. What is your real return, roughly?","template":"real_return","params":{"rate":{"choices":[5,6,7,8]},"inflation":{"choices":[5,6,7]}},"why":"Real return ≈ {rate}% − {inflation}% = {answer}. At or below zero, your money buys the same or less each year."},
{"slug":"at-72-infl","level":"ADVANCED","topic":"Inflation","emoji":"✌️","prompt":"Inflation runs at {r}% a year. Using the Rule of 72, prices double in about…","template":"rule_of_72","params":{"r":{"choices":[3,4,6,8,9,12]}},"why":"72 ÷ {r} = {answer}. The Rule of 72 works for inflation too."},
{"slug":"at-emi","level":"ADVANCED","topic":"EMI","emoji":"💻","prompt":"A laptop on “no-cost” EMI: {emi:inr} a month for {months} months plus a {fee:inr} processing fee. What do you pay in total (ignoring GST)?","template":"emi_total","params":{"emi":{"min":2000,"max":8000,"step":500},"months":{"choices":[12,18,24]},"fee":{"choices":[999,1999,2999]}},"why":"{emi:inr} × {months} + {fee:inr} = {answer}. Compare it with the upfront price, including any card discount you’d lose."},
{"slug":"at-sip","level":"ADVANCED","topic":"Investing","emoji":"📅","prompt":"You run a SIP of {amount:inr} a month for {years} years. How much of your own money did you invest?","template":"sip_invested","params":{"amount":{"min":2000,"max":20000,"step":1000},"years":{"choices":[15,20,25]}},"why":"{amount:inr} × 12 × {years} = {answer}. Everything above this at the end is growth."}

]$json$::jsonb) as x(slug text, level text, topic text, emoji text, prompt text, options jsonb, answer int, why text, template text, params jsonb)
on conflict (slug) do update set
  level = excluded.level, topic = excluded.topic, emoji = excluded.emoji, prompt = excluded.prompt,
  options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation,
  template = excluded.template, params = excluded.params, updated_at = now();


-- Scam or Legit messages. All brands are fictional.
insert into public.questions (slug, kind, level, topic, emoji, prompt, explanation, is_scam, meta)
select slug, 'SCAM', level::question_level, case when scam then 'Scam' else 'Genuine' end, '📩', body, why, scam,
       jsonb_build_object('channel', channel, 'sender', sender, 'redFlags', coalesce(flags, '[]'::jsonb))
from jsonb_to_recordset($json$[

{"slug":"sl-kyc-link","level":"BEGINNER","channel":"SMS","sender":"VM-BHRTBK","body":"Dear customer, your Bharat Bank account will be BLOCKED today. Update KYC now: bharat-bank-kyc.co/update","scam":true,"flags":["Urgent threat of blocking","Lookalike link, not the bank’s domain","Banks don’t do KYC by SMS link"],"why":"Banks never ask you to update KYC through a random link. Visit the branch or the official app."},
{"slug":"sl-otp-call","level":"BEGINNER","channel":"Call","sender":"+91 98XXX 21034","body":"“Sir, I am calling from your bank’s fraud department. Please tell me the OTP you just received so we can cancel the suspicious transaction.”","scam":true,"flags":["Asks for OTP","Unknown mobile number","Creates panic"],"why":"Nobody genuine will ever ask for your OTP. Hang up."},
{"slug":"sl-collect","level":"BEGINNER","channel":"App","sender":"UPI collect request","body":"Rahul_OLX has requested ₹4,999. Enter UPI PIN to RECEIVE payment for your sofa.","scam":true,"flags":["“Enter PIN to receive” is impossible","Collect request from a stranger"],"why":"Entering your UPI PIN always sends money. You never need it to receive."},
{"slug":"sl-lottery","level":"BEGINNER","channel":"WhatsApp","sender":"+44 7700 900123","body":"Congratulations!! Your number won ₹25,00,000 in the KBC Lucky Draw. Pay ₹8,500 processing fee to claim. 🎉","scam":true,"flags":["You never entered a lottery","Pay a fee to receive money","Foreign number"],"why":"If you have to pay to receive a prize, there is no prize."},
{"slug":"sl-job-fee","level":"BEGINNER","channel":"WhatsApp","sender":"HR Priya (TalentHub)","body":"Work from home, earn ₹3,000/day liking YouTube videos! Pay ₹999 joining fee to start today.","scam":true,"flags":["Too-good-to-be-true pay","Joining fee","Task-based “liking” jobs"],"why":"Real jobs pay you; they never charge you to join. “Like and earn” tasks are a common trap."},
{"slug":"sl-crypto","level":"BEGINNER","channel":"WhatsApp","sender":"Crypto Kings VIP 💎","body":"Join our premium signals group. Guaranteed 300% returns in 30 days! Only 5 seats left.","scam":true,"flags":["“Guaranteed” returns","Absurd 300% in a month","Fake scarcity"],"why":"No legitimate investment guarantees returns, let alone 300% a month."},
{"slug":"sl-free-recharge","level":"BEGINNER","channel":"WhatsApp","sender":"Forwarded many times","body":"Government is giving FREE ₹299 mobile recharge for 3 months to all Indians! Claim before midnight: free-recharge-yojana.xyz","scam":true,"flags":["Free offer for “everyone”","Unofficial .xyz link","Forwarded chain message","Deadline pressure"],"why":"Government schemes are announced on official .gov.in sites, not chain forwards with odd links."},
{"slug":"sl-qr-receive","level":"BEGINNER","channel":"WhatsApp","sender":"Buyer – Ankit","body":"I’ll pay ₹2,500 for your old laptop. I’m sending a QR code — just scan it and enter your PIN to receive the money.","scam":true,"flags":["Scanning a QR to “receive” money","Asks for your PIN","Rushed buyer you’ve never met"],"why":"QR codes are for paying, not receiving. Scanning and entering your PIN sends money to them."},
{"slug":"sl-gift-cards","level":"BEGINNER","channel":"Email","sender":"Your “Principal” (principal.office.desk@gmail.com)","body":"I’m in a meeting and can’t talk. Buy 5 ShopKart gift cards of ₹2,000 each and send me the codes urgently. I’ll repay you today.","scam":true,"flags":["Boss or teacher from a personal Gmail","Gift cards as payment","Urgent and can’t talk"],"why":"Gift-card requests are untraceable money grabs. Confirm in person or on a number you already have."},
{"slug":"sl-debit-alert","level":"BEGINNER","channel":"SMS","sender":"AX-BHRTBK","body":"Rs.450.00 debited from A/c XX2241 on 12-Oct at SWIGGY via UPI. Not you? Call 1800-XXX-1234 (number on your card).","scam":false,"why":"A normal transaction alert: no link, no request, and it tells you to use the number on your card."},
{"slug":"sl-otp-self","level":"BEGINNER","channel":"SMS","sender":"VK-PAYEZY","body":"482911 is your OTP to log in to PayEzy. Do NOT share this with anyone, including PayEzy staff.","scam":false,"why":"A genuine OTP you requested, with the right warning. Just don’t share it."},
{"slug":"sl-salary","level":"BEGINNER","channel":"SMS","sender":"JM-BHRTBK","body":"Your A/c XX2241 is credited with Rs.28,500.00 on 01-Nov by NEFT from ACME SOFTWARE PVT LTD (Salary).","scam":false,"why":"A plain credit alert from the bank’s sender ID. Nothing to click, nothing to share."},
{"slug":"sl-upi-received","level":"BEGINNER","channel":"App","sender":"UPI app","body":"You received ₹500 from Ananya S. for “movie tickets”. Balance updated.","scam":false,"why":"Money received shows up without any PIN. This is exactly how it should look."},
{"slug":"sl-branch-holiday","level":"BEGINNER","channel":"SMS","sender":"JM-BHRTBK","body":"Our branches will be closed on 15 Aug for Independence Day. Net banking, UPI and ATMs will work as usual.","scam":false,"why":"An information-only notice. It asks you to do nothing and has no link."},
{"slug":"sl-bill-genuine","level":"BEGINNER","channel":"SMS","sender":"VM-PWRDIS","body":"Electricity bill of ₹1,240 for consumer no. 4471XX generated. Due date 18 Nov. Pay in the official app or at the bill office.","scam":false,"why":"A routine bill with a normal due date, no threats and no link to click."},
{"slug":"sl-cashback","level":"BEGINNER","channel":"App","sender":"PayEzy app","body":"₹25 cashback credited to your PayEzy wallet for your electricity bill payment. 🎉","scam":false,"why":"A small, expected reward inside the app you used. No action or details required."},

{"slug":"sl-electricity","level":"INTERMEDIATE","channel":"SMS","sender":"+91 70XXX 88412","body":"Your electricity will be disconnected tonight at 9:30 PM as last month bill not updated. Call officer 70XXX88412 immediately.","scam":true,"flags":["Personal mobile number","Tonight deadline","Poor grammar"],"why":"Electricity boards send notices from official IDs and never threaten same-night cuts by SMS."},
{"slug":"sl-parcel","level":"INTERMEDIATE","channel":"SMS","sender":"IndPost-Help","body":"Your parcel is held due to incomplete address. Pay ₹25 redelivery fee: indpost-redeliver.in","scam":true,"flags":["Unexpected parcel","Small fee to steal card details","Fake domain"],"why":"A tiny “fee” is bait to capture your card details."},
{"slug":"sl-relative","level":"INTERMEDIATE","channel":"WhatsApp","sender":"Unknown number","body":"Hi beta, this is Mamaji’s new number. Urgent hospital emergency, please send ₹15,000 on this UPI, will return tomorrow.","scam":true,"flags":["New number claiming to be family","Urgent money request","Asks not to call"],"why":"Call the relative on their old number before sending anything."},
{"slug":"sl-screen-share","level":"INTERMEDIATE","channel":"Call","sender":"Customer Care (from Google search)","body":"“To process your refund, please install AnyDesk and share the 9-digit code.”","scam":true,"flags":["Asks to install screen-sharing app","Number found via random search result"],"why":"Screen-sharing apps give fraudsters full control of your phone. Use only official helplines from the company’s app."},
{"slug":"sl-trading-app","level":"INTERMEDIATE","channel":"WhatsApp","sender":"NiftyPro VIP Desk","body":"Our SEBI-approved VIP group made 18% this week! Download the NiftyPro Max app from this link to get institutional IPO quota.","scam":true,"flags":["App from a link, not an app store","“SEBI-approved” with no registration number","18% in a week"],"why":"Fake trading apps show made-up profits, then block withdrawals. Trade only through a registered broker’s official app."},
{"slug":"sl-courier-police","level":"INTERMEDIATE","channel":"Call","sender":"“FedXpress Courier”","body":"“A parcel in your name with illegal items was seized at customs. I am connecting you to the police for verification on a video call. Do not disconnect.”","scam":true,"flags":["Parcel you never sent","Transfer to “police” on video","Don’t-disconnect pressure"],"why":"This is the opening of a “digital arrest” scam. Real police don’t investigate over courier calls. Hang up and report on 1930."},
{"slug":"sl-reward-points","level":"INTERMEDIATE","channel":"SMS","sender":"BX-REWRDZ","body":"Your 4,850 reward points worth ₹4,850 expire TODAY! Redeem now: bharatbank-rewardz.in","scam":true,"flags":["Expires today","Lookalike domain","Points rarely equal ₹1 each"],"why":"Points phishing sites steal card details and OTPs. Check rewards only inside your bank’s app."},
{"slug":"sl-preapproved","level":"INTERMEDIATE","channel":"SMS","sender":"+91 88XXX 10293","body":"Pre-approved loan of ₹2,00,000 at 0% interest. No documents needed! Pay ₹1,499 processing fee to release funds.","scam":true,"flags":["0% interest, no documents","Fee before the loan","Personal mobile number"],"why":"Genuine lenders deduct fees from the loan; they don’t ask you to pay first to “release” money."},
{"slug":"sl-sip-confirm","level":"INTERMEDIATE","channel":"Email","sender":"noreply@growvest.in","body":"Your monthly SIP of ₹2,000 in Flexicap Mutual Fund was processed successfully. Units allotted: 33.21. View in the Growvest app.","scam":false,"why":"An information-only confirmation from the platform you already use. It asks you to do nothing risky."},
{"slug":"sl-emi-reminder","level":"INTERMEDIATE","channel":"App","sender":"Bharat Bank app","body":"Reminder: your EMI of ₹3,200 is due on 5 Nov. Keep balance in your account to avoid late fees.","scam":false,"why":"A routine in-app reminder about a loan you know you have."},
{"slug":"sl-insurance-renew","level":"INTERMEDIATE","channel":"Email","sender":"renewals@surakshainsure.co.in","body":"Your health policy renews on 20 Nov. Renew from the Suraksha app or website you used to buy it. Ignore if already paid.","scam":false,"why":"It points you to the official app/site you already use, with no link pressure."},
{"slug":"sl-refund-genuine","level":"INTERMEDIATE","channel":"SMS","sender":"AD-SHOPKR","body":"Refund of ₹1,299 for order #SK8812 initiated to your original payment method. It will reflect in 5–7 working days.","scam":false,"why":"Real refunds go back to the original payment method automatically — no details needed."},
{"slug":"sl-new-device","level":"INTERMEDIATE","channel":"SMS","sender":"JM-BHRTBK","body":"Login to Bharat Bank net banking from a new device at 10:42 PM. If this wasn’t you, call the number on the back of your card.","scam":false,"why":"A security alert with no link that sends you to the number you already have. If it wasn’t you, act on it."},
{"slug":"sl-statement","level":"INTERMEDIATE","channel":"Email","sender":"statements@bharatbank.co.in","body":"Your credit card statement for October is ready. Total due ₹8,420, due date 25 Nov. View it in the Bharat Bank app.","scam":false,"why":"A routine statement notice from the bank’s own domain, pointing you to the app instead of a link."},
{"slug":"sl-autopay","level":"INTERMEDIATE","channel":"App","sender":"UPI app","body":"AutoPay set up: ₹199/month to StreamFlix, as approved by you. Manage or cancel anytime in UPI app → AutoPay.","scam":false,"why":"Confirmation of a mandate you approved, with an easy way to cancel. Nothing to share."},

{"slug":"sl-refund-tax","level":"ADVANCED","channel":"Email","sender":"refunds@incometax-gov-refund.com","body":"You are eligible for an income tax refund of ₹18,240. Submit your card details within 24 hours to receive it.","scam":true,"flags":["Not a .gov.in domain","Asks for card details","24-hour pressure"],"why":"Tax refunds go straight to your bank account. The department never asks for card details."},
{"slug":"sl-lookalike","level":"ADVANCED","channel":"Email","sender":"alerts@bharatbank.co.in.secure-verify.com","body":"Unusual sign-in detected on your account. Verify your identity within 2 hours to avoid suspension: [Verify now]","scam":true,"flags":["Real domain is secure-verify.com, not the bank","2-hour deadline","“Verify” button"],"why":"Read a domain from the right: this mail comes from secure-verify.com. The bank’s name at the start is decoration."},
{"slug":"sl-pre-ipo","level":"ADVANCED","channel":"WhatsApp","sender":"Institutional Desk – Rhea","body":"Exclusive pre-IPO allotment at 40% below listing price. Transfer to our company account (A/c name: Rakesh K.) to lock your shares today.","scam":true,"flags":["“Company” account in a person’s name","Guaranteed discount to listing","Today-only"],"why":"Real IPO applications go through your own broker or bank (ASBA/UPI mandate). Money never goes to an individual’s account."},
{"slug":"sl-digital-arrest","level":"ADVANCED","channel":"Call","sender":"“Cyber Crime Branch” (video call)","body":"“You are under digital arrest for money laundering. Stay on video, tell no one, and move your savings to an RBI safe account for verification.”","scam":true,"flags":["“Digital arrest” doesn’t exist","Keep it secret","Move money to a “safe account”"],"why":"No agency arrests people over video or holds money in “safe accounts”. Disconnect and report on 1930."},
{"slug":"sl-apk","level":"ADVANCED","channel":"WhatsApp","sender":"Rohit (saved contact)","body":"Bro check my wedding invite 💌 Wedding_Invite.apk","scam":true,"flags":["An .apk app file, not a photo or PDF","Even from a saved contact (account may be hacked)"],"why":"APK files install apps outside the Play Store and can read your SMS and OTPs. Never install them from chats."},
{"slug":"sl-wrong-credit","level":"ADVANCED","channel":"SMS","sender":"+91 90XXX 55120","body":"Rs 10,000.00 credited to a/c XX2241 by UPI. (A minute later a caller says he sent it by mistake and begs you to send it back.)","scam":true,"flags":["“Credit” SMS from a personal number","Emotional pressure to send money back"],"why":"Check your real balance in the bank app. Fake credit SMS are used to trick you into “returning” money you never got."},
{"slug":"sl-offer-letter","level":"ADVANCED","channel":"Email","sender":"hr@acme-software-careers.com","body":"Congratulations! You’re selected as Data Analyst (₹9 LPA). Complete background verification by paying ₹4,500 to our verification partner within 48 hours.","scam":true,"flags":["Offer without a real interview","Lookalike careers domain","Pay for verification"],"why":"Employers pay for background checks themselves. Any fee to secure a job offer is a scam."},
{"slug":"sl-policy-bonus","level":"ADVANCED","channel":"Call","sender":"“Suraksha Life Claims Dept.”","body":"“Your old policy has a ₹3.2 lakh bonus pending. Pay ₹18,000 as GST to release the amount today.”","scam":true,"flags":["Unexpected bonus","Pay tax to receive money","Call, not a written notice"],"why":"Insurers pay what’s due directly to your bank account. Paying a fee or “GST” to release money is always a scam."},
{"slug":"sl-sim-kyc","level":"ADVANCED","channel":"SMS","sender":"+91 79XXX 33018","body":"Your SIM will be blocked in 24 hrs due to incomplete eKYC. Call executive at 79XXX33018 to update.","scam":true,"flags":["Personal number, not the operator’s ID","24-hour threat","Leads to SIM-swap"],"why":"Operators don’t block SIMs via SMS threats. These calls aim to get OTPs for a SIM swap."},
{"slug":"sl-broker-notice","level":"ADVANCED","channel":"Email","sender":"updates@tradelane.in","body":"Quarterly settlement: as per exchange rules, unused funds of ₹1,250 in your TradeLane account have been returned to your linked bank account.","scam":false,"why":"Brokers really do return idle funds every quarter by rule. No action needed."},
{"slug":"sl-contract-note","level":"ADVANCED","channel":"Email","sender":"contractnotes@tradelane.in","body":"Contract note for trades on 12 Nov: Bought 5 shares of GreenGrid Power at ₹412.30. The PDF password is your PAN in capitals.","scam":false,"why":"Brokers must send contract notes after every trade day. It matches a trade you made and asks for nothing."},
{"slug":"sl-cas","level":"ADVANCED","channel":"Email","sender":"noreply@growvest.in","body":"Your Consolidated Account Statement for October is attached. It lists all your mutual fund holdings. Password: PAN + date of birth.","scam":false,"why":"A routine statement from your platform. Password-protected PDFs with your own details are standard."},
{"slug":"sl-rate-change","level":"ADVANCED","channel":"SMS","sender":"JM-BHRTBK","body":"From 1 Dec, the interest rate on your home loan XX7781 changes from 8.75% to 8.50% p.a. following the repo rate change. Your EMI stays the same; tenure is reduced.","scam":false,"why":"Floating-rate loans really do change with the repo rate. No link, no request — just information."},
{"slug":"sl-it-refund","level":"ADVANCED","channel":"SMS","sender":"VM-ITDEFL","body":"Refund of Rs 4,120 for AY 2025-26 has been credited to your pre-validated bank account XX2241.","scam":false,"why":"Real refunds land in your pre-validated account and the SMS asks for nothing. Compare it with the card-details “refund” scam."},
{"slug":"sl-ipo-mandate","level":"ADVANCED","channel":"App","sender":"UPI app","body":"UPI mandate request of ₹14,800 from TradeLane for the IPO application you placed. Approve before 5 PM tomorrow.","scam":false,"why":"IPO applications via UPI work exactly like this: a mandate for an application you made, approved in your own app."},
{"slug":"sl-card-blocked","level":"ADVANCED","channel":"SMS","sender":"JM-BHRTBK","body":"Your Bharat Bank credit card XX9921 has been temporarily blocked as requested by you in the app. To unblock, use the app.","scam":false,"why":"Confirms an action you took and points you back to the app. No link, no call-back number, no request."}

]$json$::jsonb) as x(slug text, level text, channel text, sender text, body text, scam boolean, flags jsonb, why text)
on conflict (slug) do update set
  level = excluded.level, topic = excluded.topic, prompt = excluded.prompt, explanation = excluded.explanation,
  is_scam = excluded.is_scam, meta = excluded.meta, updated_at = now();
